-- ============================================================
-- AS STORE — COMPLETE DATABASE SETUP & SEED SCRIPT
-- Run this entire script in your NEW Supabase Project:
-- Supabase Dashboard > SQL Editor > New query > Paste & Run
-- ============================================================

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. DROP EXISTING TABLES (IF ANY)
DROP TABLE IF EXISTS public.order_items CASCADE;
DROP TABLE IF EXISTS public.orders CASCADE;
DROP TABLE IF EXISTS public.coupon_usage CASCADE;
DROP TABLE IF EXISTS public.product_images CASCADE;
DROP TABLE IF EXISTS public.product_variants CASCADE;
DROP TABLE IF EXISTS public.products CASCADE;
DROP TABLE IF EXISTS public.coupons CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;
DROP TABLE IF EXISTS public.settings CASCADE;
DROP TABLE IF EXISTS public.profiles CASCADE;

-- 2. CATEGORIES TABLE
CREATE TABLE public.categories (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  name text NOT NULL,
  slug text NOT NULL UNIQUE,
  image_url text,
  description text,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 3. PRODUCTS TABLE
CREATE TABLE public.products (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  name text NOT NULL,
  slug text NOT NULL UNIQUE,
  description text DEFAULT '',
  short_description text DEFAULT '',
  specifications jsonb NOT NULL DEFAULT '[]'::jsonb,
  key_features jsonb DEFAULT '[]'::jsonb,
  bundle_offers jsonb DEFAULT '[]'::jsonb,
  price numeric(12,2) NOT NULL CHECK (price >= 0),
  old_price numeric(12,2) CHECK (old_price >= 0),
  discount numeric(5,2) GENERATED ALWAYS AS (
    CASE
      WHEN old_price IS NOT NULL AND old_price > 0 AND old_price > price
        THEN round(((old_price - price) / old_price) * 100, 2)
      ELSE 0
    END
  ) STORED,
  category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL,
  sort_order integer NOT NULL DEFAULT 0,
  stock_status text NOT NULL DEFAULT 'in_stock' CHECK (stock_status IN ('in_stock', 'out_of_stock', 'low_stock')),
  featured boolean NOT NULL DEFAULT false,
  best_seller boolean NOT NULL DEFAULT false,
  new_arrival boolean NOT NULL DEFAULT false,
  free_delivery boolean NOT NULL DEFAULT false,
  active boolean NOT NULL DEFAULT true,
  sku text,
  purchase_price numeric(12,2),
  wholesale_price numeric(12,2),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_products_category ON public.products(category_id);
CREATE INDEX IF NOT EXISTS idx_products_active ON public.products(active);
CREATE INDEX IF NOT EXISTS idx_products_slug ON public.products(slug);

-- 4. PRODUCT IMAGES
CREATE TABLE public.product_images (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  image_url text NOT NULL,
  is_primary boolean NOT NULL DEFAULT false,
  sort_order int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_product_images_product ON public.product_images(product_id);

-- 5. PRODUCT VARIANTS
CREATE TABLE public.product_variants (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  variant_type text NOT NULL DEFAULT 'color',
  variant_name text NOT NULL,
  color_value text,
  image_url text,
  is_active boolean NOT NULL DEFAULT true,
  sort_order int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_product_variants_product ON public.product_variants(product_id);

-- 6. COUPONS
CREATE TABLE public.coupons (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  code text NOT NULL UNIQUE,
  discount_type text NOT NULL CHECK (discount_type IN ('percentage', 'fixed')),
  discount_value numeric(12,2) NOT NULL CHECK (discount_value >= 0),
  minimum_order numeric(12,2) NOT NULL DEFAULT 0,
  maximum_discount numeric(12,2),
  expiry_date timestamptz,
  usage_limit int,
  times_used int NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  applicable_product_ids uuid[] DEFAULT '{}'::uuid[],
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 7. SETTINGS
CREATE TABLE public.settings (
  id int PRIMARY KEY DEFAULT 1,
  business_name text NOT NULL DEFAULT 'AS Store',
  logo_url text,
  whatsapp_number text NOT NULL DEFAULT '+92 320 1042634',
  email text DEFAULT 'support@asstore.pk',
  address text DEFAULT 'Lahore, Punjab, Pakistan',
  facebook text,
  instagram text,
  tiktok text,
  business_greeting text NOT NULL DEFAULT 'Hello AS Store!',
  order_message_template text NOT NULL DEFAULT 'Hello AS Store!

I want to confirm my order.',
  currency text NOT NULL DEFAULT 'PKR',
  currency_symbol text NOT NULL DEFAULT 'Rs.',
  prevent_negative_profit boolean DEFAULT true,
  delivery_charges numeric(12,2) DEFAULT 200,
  free_shipping_threshold numeric(12,2) DEFAULT 3000,
  bundle_tier1_threshold numeric(12,2) DEFAULT 3000,
  bundle_tier1_percent numeric(5,2) DEFAULT 5,
  bundle_tier2_threshold numeric(12,2) DEFAULT 6000,
  bundle_tier2_percent numeric(5,2) DEFAULT 10,
  online_payment_enabled boolean DEFAULT true,
  payment_method_name text DEFAULT 'JazzCash',
  payment_account_name text DEFAULT 'AS Store',
  payment_account_number text DEFAULT '03264227243',
  payment_accounts jsonb DEFAULT '[]'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT single_row CHECK (id = 1)
);

-- 8. ORDERS & ORDER ITEMS
CREATE SEQUENCE IF NOT EXISTS public.as_order_number_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE public.orders (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  order_number text UNIQUE,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'pending_payment', 'approved', 'processing', 'shipped', 'delivered', 'cancelled', 'rejected')),
  customer_id uuid,
  customer_name text NOT NULL,
  phone text NOT NULL,
  city text NOT NULL,
  address text NOT NULL,
  subtotal numeric(12,2) NOT NULL DEFAULT 0,
  delivery_charges numeric(12,2) NOT NULL DEFAULT 0,
  coupon_discount numeric(12,2) NOT NULL DEFAULT 0,
  bundle_discount numeric(12,2) NOT NULL DEFAULT 0,
  total_amount numeric(12,2) NOT NULL DEFAULT 0,
  payment_status text NOT NULL DEFAULT 'pending',
  payment_method text DEFAULT 'Cash on Delivery',
  payment_reference text,
  order_source text NOT NULL DEFAULT 'web',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  approved_at timestamptz,
  approved_by uuid,
  rejected_at timestamptz,
  admin_notification_sent boolean NOT NULL DEFAULT false,
  customer_notification_sent boolean NOT NULL DEFAULT false,
  admin_notes text
);

CREATE TABLE public.order_items (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  product_id uuid REFERENCES public.products(id) ON DELETE SET NULL,
  product_name text NOT NULL,
  variant_name text,
  unit_price numeric(12,2) NOT NULL,
  purchase_price numeric(12,2) DEFAULT 0,
  quantity int NOT NULL DEFAULT 1 CHECK (quantity > 0),
  line_total numeric(12,2) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 9. STORED PROCEDURES
CREATE OR REPLACE FUNCTION public.approve_order(
  p_order_id uuid,
  p_admin_id uuid DEFAULT NULL,
  p_admin_notes text DEFAULT NULL
)
RETURNS public.orders AS $$
DECLARE
  v_order public.orders;
  v_seq bigint;
  v_order_num text;
BEGIN
  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % not found', p_order_id;
  END IF;

  IF v_order.status NOT IN ('pending', 'pending_payment') THEN
    RAISE EXCEPTION 'Order % cannot be approved because status is %', p_order_id, v_order.status;
  END IF;

  v_seq := nextval('public.as_order_number_seq');
  v_order_num := 'AS-' || lpad(v_seq::text, 4, '0');

  UPDATE public.orders
  SET order_number = v_order_num,
      status = 'approved',
      approved_at = now(),
      updated_at = now()
  WHERE id = p_order_id
  RETURNING * INTO v_order;

  RETURN v_order;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.increment_coupon_usage(coupon_id uuid)
RETURNS void AS $$
BEGIN
  UPDATE public.coupons
  SET times_used = times_used + 1
  WHERE id = coupon_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 10. ROW LEVEL SECURITY (RLS) POLICIES
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_images ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public categories select" ON public.categories FOR SELECT USING (true);
CREATE POLICY "Public products select" ON public.products FOR SELECT USING (true);
CREATE POLICY "Public images select" ON public.product_images FOR SELECT USING (true);
CREATE POLICY "Public variants select" ON public.product_variants FOR SELECT USING (true);
CREATE POLICY "Public coupons select" ON public.coupons FOR SELECT USING (true);
CREATE POLICY "Public settings select" ON public.settings FOR SELECT USING (true);
CREATE POLICY "Public orders insert" ON public.orders FOR INSERT WITH CHECK (true);
CREATE POLICY "Public order_items insert" ON public.order_items FOR INSERT WITH CHECK (true);
CREATE POLICY "Public orders select" ON public.orders FOR SELECT USING (true);
CREATE POLICY "Public order_items select" ON public.order_items FOR SELECT USING (true);

