INSERT INTO public.products (id, name, slug, description, short_description, specifications, key_features, bundle_offers, price, old_price, category_id, sort_order, stock_status, featured, best_seller, new_arrival, free_delivery, active, sku, purchase_price, wholesale_price, created_at, updated_at) VALUES ('9f0d9e8b-77f0-4b4f-8275-7a1a5261daf4', 'Yolo Type-C Fast Charging & Data Sync Cable', 'yolo-cable-c-type', 'Upgrade your charging and data transfer experience with the Yolo Type-C Cable. Engineered for speed and durability, this cable delivers rapid power delivery to keep your smartphones, tablets, and Bluetooth speakers powered up throughout the day. ⚡

Built with high-grade reinforced connectors and a tangle-free braided exterior, it withstands daily wear and tear effortlessly. Whether you''re transferring heavy files or quick-charging your devices, the Yolo Type-C cable ensures stable and secure performance every single time. 🔋

Key Features:
• High-speed data transfer and power delivery
• Premium tangle-free braided design for extra durability
• Reinforced stress points to prevent fraying
• Universal compatibility with Type-C enabled devices

